Section CANSEC1. Context {rc : runConstT}.
Section X4S0.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : fmem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX1) (cbs : list byte).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Hypothesis TOK : x1_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (2 * 2^tl)) (x1_bytes' cells).
  Hypothesis LCB : zlen cbs = 2 * 2^tl.
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl + 1.
  Hypothesis D0 : 0 <= DST.
  Hypothesis DP : 0 < dcap -> 8 <= DST.
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 2 * 2^tl <= lo.
  Hypothesis DJ1 : DT + 4 + 2 * 2^tl <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.

  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation XB l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cells cbs
                      TOK ECB LCB MTL TLM D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47) (only parsing).
  Notation X4F' mm spl bd4 := (X4F ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs mm spl bd4).

  Notation DW := [(SP - 4096, SP); (DST, DST + dcap)].
  Notation FRS := [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  (* [comment removed for export] *)
  Definition X4S0 (mm : fmem) : Prop :=
    (exists buf, u8arr psegs mm DST (map (Z_to_bv 8) buf) /\ zlen buf = dcap)
    /\ bytes_at psegs mm SS (map (Z_to_bv 8) src)
    /\ bytes_at psegs mm (DT + 4) cbs
    /\ bytes_at psegs mm DT [Z_to_bv 8 mtl; Z_to_bv 8 0; Z_to_bv 8 tl; Z_to_bv 8 mtl]
    /\ stk psegs mm lo (SP + -104)
    /\ rw_cells psegs mm (SP + -104) FRS
    /\ mem_inv psegs mm /\ munch DW m0 mm /\ wmono psegs m0 mm.

  Notation L1 := (jt_len src 0). Notation L2 := (jt_len src 2). Notation L3 := (jt_len src 4).
  Notation SEG := ((dcap + 3) / 4).
  (* [comment removed for export] *)
  Notation SPL0 j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j104 j112 j120 j128 j136 j144 j152 :=
    [CB 8 j0; CB 8 j8; CB 8 j16; CB 8 j24; CB 8 j32; CB 8 j40; CB 8 j48; CB 8 j56; CB 8 j64; CB 8 j72; CB 8 j80; CB 8 j88;
     CB 8 j96; CB 8 j104; CB 8 j112; CB 8 j120; CB 8 j128; CB 8 j136; CB 8 j144; CB 8 j152].

  (* [comment removed for export] *)
  Notation P1 pc mm t0 t1 t2 a0 a5 a6 x21 x22 x23 x24 x26 :=
    (MS (mkR (Z_to_bv 64 n) (Z_to_bv 64 (SP + -416)) gp tp t0 t1 t2 (Z_to_bv 64 (SS + 6)) (Z_to_bv 64 (SS + 6 + L1)) a0
             (Z_to_bv 64 L2) (Z_to_bv 64 (L1 + L2 + L3 + 6)) (Z_to_bv 64 L3) (Z_to_bv 64 L1) a5 a6 (Z_to_bv 64 (DST + 2 * SEG)) (Z_to_bv 64 SS)
             (Z_to_bv 64 (DST + 3 * SEG)) (Z_to_bv 64 (DST + SEG)) x21 x22 x23 x24 (Z_to_bv 64 SEG) x26 (Z_to_bv 64 dcap)
             (Z_to_bv 64 DST) (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 DT))
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).
  Notation FR0 mm j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j104 j112 j120 j128 j136 j144 j152 jb :=
    (X4F' mm (SPL0 j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j104 j112 j120 j128 j136 j144 j152) [CB 40 jb]).
  Notation FACTS0 := (6 <= dcap /\ 10 <= n /\ 1 <= L1 /\ L1 + L2 + L3 + 6 <= n /\ 3 * SEG <= dcap /\ 0 <= L2 /\ 0 <= L3).

  Hypothesis HB1 : forall mm j0 j8 j16 j24 j32 j40 j48 j56 j64 j72 j80 j88 j96 j104 j112 j120 j128 j136 j144 j152 jb
